-- 자동 생성 파일입니다(scripts/seed-terms.mjs). 직접 고치지 말고 terms.json을 고친 뒤 npm run seed.
on conflict (key) do update set
  name = excluded.name, aka = excluded.aka, def = excluded.def,
  sources = excluded.sources, sort = excluded.sort, updated_at = now();

delete from public.terms where key not in ('deunggi', 'gapgu', 'eulgu', 'geunjeodang', 'chaegwon', 'seonsunwi', 'sintak', 'gaapryu', 'geonchuk', 'wiban', 'jeonsega', 'imdaein', 'teukyak', 'hwakjeong', 'singo', 'jeonip', 'daehang', 'usun', 'hug', 'gaengsin', 'seaek');
