insert into public.terms (key, name, aka, def, sources, sort) values
  ('deunggi', '등기사항증명서', '등기부등본', '집의 이력서 같은 공문서예요. 표제부(집 주소·면적), 갑구(누가 주인인지), 을구(집에 걸린 빚)로 나뉘어 있어요. 인터넷등기소에서 누구나 떼 볼 수 있어요.', '{1,17}', 1),
  ('gapgu', '갑구', '', '등기부에서 소유권에 관한 부분이에요. 지금 주인이 누구인지, 압류·가압류·신탁처럼 소유권을 묶는 기록이 있는지 여기서 봐요.', '{1}', 2),
  ('eulgu', '을구', '', '등기부에서 소유권 말고 다른 권리가 적힌 부분이에요. 근저당권, 전세권, 임차권처럼 집에 걸린 빚과 권리가 여기 나와요. ''을구 기록 없음''이면 걸린 빚이 없다는 뜻이에요.', '{1}', 3),
  ('geunjeodang', '근저당권', '', '집주인이 이 집을 담보로 돈을 빌렸다는 표시예요. 집이 경매로 넘어가면 근저당을 가진 은행이 순서에 따라 먼저 돈을 가져가요.', '{1,2}', 4),
  ('chaegwon', '채권최고액', '', '근저당권자가 이 집에서 최대로 받아 갈 수 있는 금액이에요. 실제 빌린 돈보다 크게 잡히는 경우가 많아서, 위험을 따질 때는 이 금액을 기준으로 보는 게 안전해요.', '{1}', 5),
  ('seonsunwi', '선순위', '', '나보다 먼저 권리를 가진 사람이에요. 먼저 설정된 근저당(은행)이나 먼저 들어와 확정일자를 받은 다른 세입자가 해당해요. 경매 때는 선순위부터 돈을 받아 가요.', '{2,14}', 6),
  ('sintak', '신탁등기', '', '집 소유권이 신탁회사로 넘어가 있다는 기록이에요. 이런 집은 등기상 주인이 신탁회사라서, 원래 집주인 혼자서는 임대할 권한이 없을 수 있어요.', '{15}', 7),
  ('gaapryu', '압류·가압류', '', '집주인의 빚 때문에 집을 함부로 팔거나 처분하지 못하게 묶어 둔 기록이에요. 갑구에 있으면 경매로 이어질 수 있다는 신호예요.', '{1,8}', 8),
  ('geonchuk', '건축물대장', '', '건물의 용도, 면적, 층수, 위반 여부가 적힌 공문서예요. 세움터나 정부24에서 무료로 볼 수 있어요. 등기부와 대조해서 주택 용도가 맞는지 확인해요.', '{15,18}', 9),
  ('wiban', '위반건축물', '', '허가 없이 증축하거나 용도를 바꾼 건물이에요. 건축물대장 맨 위에 ''위반건축물''이라고 표시돼요. 대출이나 보증보험이 거절되는 원인이 되기도 해요.', '{15}', 10),
  ('jeonsega', '전세가율', '깡통전세', '집값 대비 보증금의 비율이에요. 서울시는 70%를 넘지 않는 게 좋다고 안내해요. 집에 걸린 빚까지 더한 금액이 집값에 가까우면 집이 팔려도 보증금을 다 돌려받지 못하는 깡통전세가 될 수 있어요. 시세는 국토부 실거래가 공개시스템에서 확인해요.', '{15,16}', 11),
  ('imdaein', '임대인 정보 제시 의무', '', '임대차계약을 맺을 때 집주인은 이 집의 확정일자 부여 현황(먼저 들어온 세입자 정보)과 세금 체납 여부(납세증명서)를 세입자에게 보여 줘야 해요. 주택임대차보호법 제3조의7에 있는 내용이에요.', '{1,14}', 12),
  ('teukyak', '특약', '특약사항', '계약서의 기본 조항 외에 두 사람이 따로 정한 약속이에요. 다만 주택임대차보호법보다 세입자에게 불리한 약정은 효력이 없어요(같은 법 제10조).', '{14}', 13),
  ('hwakjeong', '확정일자', '', '계약서가 그날 존재했다는 것을 공적으로 증명하는 날짜 도장이에요. 주민센터나 인터넷등기소에서 받을 수 있고, 임대차 신고를 하면 자동으로 받은 것으로 처리돼요.', '{2,3}', 14),
  ('singo', '임대차 신고', '전월세 신고제', '신고 지역에서 보증금 6천만 원 또는 월세 30만 원을 넘는 계약은 계약일부터 30일 안에 신고해야 해요. 수도권 전역, 광역시, 세종, 도의 시 지역이 대상이고, 기한을 넘기면 과태료가 붙어요.', '{3,4,5}', 15),
  ('jeonip', '전입신고', '', '새 집으로 주소를 옮겼다고 신고하는 거예요. 이사한 날부터 14일 안에 주민센터나 정부24에서 해요. 대항력을 얻으려면 꼭 필요해요.', '{6,7}', 16),
  ('daehang', '대항력', '', '집주인이 바뀌어도 ''계약 기간 동안 여기 살고, 보증금을 돌려받을 때까지 나가지 않겠다''고 주장할 수 있는 힘이에요. 집에 들어가 살고(인도) 전입신고를 마친 다음 날 0시에 생겨요.', '{2,14}', 17),
  ('usun', '우선변제권', '', '집이 경매로 넘어갔을 때 나보다 뒤에 생긴 권리자보다 먼저 보증금을 돌려받을 권리예요. 대항력(입주+전입)과 확정일자를 모두 갖춰야 생겨요.', '{2,14}', 18),
  ('hug', '전세보증금반환보증', '전세보증보험', '계약이 끝났는데 집주인이 보증금을 돌려주지 않으면, 주택도시보증공사(HUG)가 먼저 돌려주는 보증 상품이에요. 계약 기간의 절반이 지나기 전에 신청해야 해요.', '{8,9}', 19),
  ('gaengsin', '계약갱신요구권', '', '계약 만료 6개월 전부터 2개월 전 사이에 세입자가 요구하면, 집주인은 정당한 사유 없이 거절하지 못해요. 한 번 쓸 수 있고 2년이 연장되며, 보증금·월세 인상은 5%까지예요.', '{14,2}', 20),
  ('seaek', '월세 세액공제', '', '무주택 세대주이면서 총급여 8천만 원 이하인 근로자가 낸 월세의 15~17%를 연말정산 때 세금에서 빼 주는 제도예요. 계약서 주소와 주민등록 주소가 같아야 해요.', '{10}', 21)
